INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-54-account_updated', 'account_updated', 'Username, Email, atau Nomor Telepon Diubah', 'whatsapp', NULL, '🔐 *DATA AKUN DIPERBARUI*\n\nHalo *{nama_peserta}*, username, email, atau nomor telepon akun Anda telah diubah.\n\nUsername: *{username}*\nEmail: *{email}*\nNomor telepon: *{phone}*\n\nJika Anda tidak melakukan atau menyetujui perubahan ini, segera hubungi admin.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-54-password_changed', 'password_changed', 'Password Diubah oleh Pemilik Akun', 'whatsapp', NULL, '🔐 *PASSWORD AKUN BERHASIL DIUBAH*\n\nHalo *{nama_peserta}*, password akun Anda baru saja diubah. Pesan ini hanya sebagai konfirmasi dan tidak memuat password.\n\nJika Anda tidak melakukan perubahan ini, segera hubungi admin.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-0020-password-reset', 'password_reset', 'Password Direset (Kredensial Baru)', 'whatsapp', NULL, '🔐 *PASSWORD AKUN DIRESET*\n\nHalo *{nama_peserta}*,\nPassword akun Anda telah direset oleh admin. Berikut kredensial login terbaru Anda:\n👤 Username: *{username}*\n🔑 Password Baru: *{password}*\n🌐 Link Login: {link_login}\n\nSegera login dan ganti password Anda ke yang lebih aman.\n\nPanitia PPDB PTDARRAHMAN', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-0019-user-created', 'user_created', 'Akun Admin Dibuat oleh Superadmin', 'whatsapp', NULL, '👤 *AKUN ADMIN DIBUAT*\n\nAssalamualaikum *{nama_peserta}*,\nAkun Anda di sistem PTDARRAHMAN telah dibuat oleh Superadmin.\n\nData Login:\n👤 Username: *{username}*\n🔑 Password: *{password}*\n🌐 Link Login: {link_login}\n\nSegera login dan ganti password Anda.\n\nAdmin PTDARRAHMAN', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1001-reg-account', 'registration_account_created', 'Pendaftaran Akun Berhasil', 'whatsapp', NULL, '📢 *Pendaftaran Akun Berhasil!*\n\nAssalamu\'alaikum / Halo *{nama_peserta}*,\nTerima kasih telah mendaftar di *{nama_sekolah}*. Akun PPDB Anda telah berhasil dibuat.\n\nBerikut adalah detail akses Anda:\n👤 Username: *{username}*\n🔑 Password: *{password}*\n🌐 Link Login: *{link_login}*\n\n⚠️ *Penting:*\nLangkah Anda selanjutnya adalah melakukan *Pembayaran Biaya Formulir*. Harap segera login ke sistem untuk melihat tagihan Anda. Batas akhir pembayaran formulir adalah sampai gelombang pendaftaran ditutup pada *{tanggal_tutup_gelombang}*.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notif-1002-payment-formulir-succ', 'payment_success_formulir', 'Pembayaran Formulir Berhasil', 'whatsapp', NULL, '✅ *Pembayaran Formulir Berhasil!*\n\nHalo *{nama_peserta}*, pembayaran formulir Anda telah kami terima. Silakan submit dokumen melalui dashboard agar dapat ditinjau panitia: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notif-1004-payment-rem-monday', 'payment_reminder_monday', 'Pengingat Bayar Formulir (Senin)', 'whatsapp', NULL, '🔔 *PENGINGAT PEMBAYARAN FORMULIR*\n\nHalo *{nama_peserta}*, pembayaran formulir Anda masih belum kami terima. Silakan lanjutkan pembayaran sebelum gelombang *{nama_gelombang}* ditutup pada *{tanggal_tutup}*.\n\nLanjutkan pendaftaran: *{link_pembayaran}*\n\nAbaikan pesan ini jika Anda sudah membayar.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-0004-payment-expired', 'payment_expired', 'Pembayaran Formulir Kedaluwarsa', 'whatsapp', NULL, '❌ *MASA PEMBAYARAN FORMULIR BERAKHIR*\n\nHalo *{nama_peserta}*,\n\nTagihan pembayaran formulir Anda telah kedaluwarsa dan dibatalkan. Tagihan ini tidak dapat dibayar lagi. Silakan mendaftar kembali jika gelombang berikutnya tersedia.\n\nTerima kasih,\nPanitia PPDB Pesantren Tahfidz Qur\'an dan Digital Ar-Rahman', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-0055-documents-submitted', 'documents_submitted', 'Dokumen Dikirim untuk Verifikasi', 'whatsapp', NULL, '📩 *DOKUMEN BERHASIL DIKIRIM*\n\nHalo *{nama_peserta}*, dokumen Anda sudah dikirim untuk ditinjau panitia. Pantau status dan informasi revisi melalui dashboard: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1005-doc-rejected-revision', 'document_rejected_revision', 'Dokumen Ditolak — Perlu Revisi', 'whatsapp', NULL, '⚠️ *Pemberitahuan Revisi Dokumen PPDB*\n\nHalo *{nama_peserta}*,\nTim kami telah memeriksa dokumen yang Anda unggah. Mohon maaf, dokumen Anda belum dapat divalidasi karena alasan berikut:\n\n❌ *{alasan_penolakan}*\n\n🔄 *Langkah Selanjutnya:*\nAgar dapat melanjutkan ke tahap Ujian, silakan login ke *{link_aplikasi}* dan unggah ulang dokumen perbaikan sesegera mungkin.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1006-doc-approved', 'document_approved', 'Dokumen Disetujui — Jadwal Ditetapkan Panitia', 'whatsapp', NULL, '✅ *DOKUMEN PENDAFTARAN DISETUJUI*\n\nHalo *{nama_peserta}*, dokumen persyaratan Anda telah disetujui. Jadwal seleksi ditetapkan oleh panitia dan akan dikirim melalui WhatsApp serta dashboard. Anda tidak perlu memilih jadwal sendiri: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1009-session-confirmed', 'session_confirmed', 'Jadwal Seleksi Ditetapkan atau Diubah', 'whatsapp', NULL, '📅 *JADWAL SELEKSI DITETAPKAN / DIPERBARUI*\n\nHalo *{nama_peserta}*, jadwal *{nama_ujian}* Anda telah ditetapkan atau diperbarui.\n\n📆 Tanggal: *{tanggal}*\n⏰ Waktu: *{jam_mulai} - {jam_selesai}*\n📍 Lokasi/Link: *{lokasi_atau_link}*\n\nJadwal ditetapkan oleh panitia; Anda tidak perlu memilih sesi. Harap hadir/bergabung 15 menit lebih awal. Detail tersedia di: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-0073-session-broadcast', 'selection_session_broadcast', 'Informasi Tambahan Sesi Seleksi', 'whatsapp', NULL, 'Halo *{nama_peserta}*,\n\nInformasi untuk sesi *{session_name}*:\n{custom_message}\n\nTerima kasih,\nPanitia PPDB PTDARRAHMAN', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-54-assessment_stage_completed', 'assessment_stage_completed', 'Tahap Penilaian Selesai', 'whatsapp', NULL, '✅ *TAHAP PENILAIAN SELESAI*\n\nHalo *{nama_peserta}*, tahap *{nama_tahap}* telah selesai dan dicatat.\n\nPantau dashboard untuk informasi jadwal tahap berikutnya atau hasil pendaftaran: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-54-registration_result_passed', 'registration_result_passed', 'Hasil Pendaftaran: Lulus', 'whatsapp', NULL, '🎉 *HASIL PENDAFTARAN: LULUS*\n\nSelamat *{nama_peserta}*, Anda dinyatakan *LULUS* dalam proses pendaftaran Pesantren Tahfidz Qur\'an dan Digital Ar-Rahman.\n\nSilakan buka laman Hasil Pendaftaran di {link_aplikasi} untuk melihat persetujuan, meninjau Letter of Acceptance (LoA), dan menyelesaikan tanda tangan. Rincian biaya pendidikan tercantum pada LoA; penyetoran dilakukan di luar aplikasi.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-59-registration_result_conditiona', 'registration_result_conditional', 'Hasil Pendaftaran: Diterima Bersyarat', 'whatsapp', NULL, '📋 *HASIL PENDAFTARAN: DITERIMA BERSYARAT*\n\nHalo *{nama_peserta}*, berdasarkan keputusan panitia PPDB Pesantren Tahfidz Qur\'an dan Digital Ar-Rahman, hasil pendaftaran Anda saat ini *DITERIMA BERSYARAT*.\n\nCatatan panitia: {catatan}\n\nSilakan hubungi panitia untuk penjelasan syarat berkelanjutan dan pantau laman Hasil Pendaftaran: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-59-registration_result_waitlist', 'registration_result_waitlist', 'Hasil Pendaftaran: Cadangan', 'whatsapp', NULL, '📌 *HASIL PENDAFTARAN: CADANGAN*\n\nHalo *{nama_peserta}*, berdasarkan keputusan panitia PPDB Pesantren Tahfidz Qur\'an dan Digital Ar-Rahman, Anda masuk dalam daftar *CADANGAN*.\n\nCatatan panitia: {catatan}\n\nStatus bisa naik menjadi Diterima apabila terjadi kuota; pantau laman Hasil Pendaftaran: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('nt-54-registration_result_failed', 'registration_result_failed', 'Hasil Pendaftaran: Tidak Lulus', 'whatsapp', NULL, '📢 *HASIL PENDAFTARAN: TIDAK LULUS*\n\nHalo *{nama_peserta}*, terima kasih telah mengikuti seluruh tahapan penilaian PPDB Pesantren Tahfidz Qur\'an dan Digital Ar-Rahman.\n\nDengan berat hati kami sampaikan bahwa hasil pendaftaran Anda saat ini *TIDAK LULUS*. Semoga tetap semangat dan memperoleh kesempatan terbaik.', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-0056-loa-signed', 'loa_signed', 'LoA Ditandatangani — PPDB Selesai', 'whatsapp', NULL, '✅ *LOA BERHASIL DITANDATANGANI*\n\nHalo *{nama_peserta}*, LoA Anda telah ditandatangani oleh orang tua/wali. Alur pendaftaran PPDB Anda telah selesai. Silakan simpan LoA pada dashboard: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1016-reminder-upload-docs', 'reminder_upload_docs_h3', 'Pengingat Submit Dokumen H+3', 'whatsapp', NULL, '🔔 *PENGINGAT SUBMIT DOKUMEN*\n\nHalo *{nama_peserta}*, pembayaran formulir Anda telah berhasil, tetapi Anda belum submit dokumen apa pun. Silakan submit dokumen melalui dashboard: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1021-reminder-exam-h2', 'reminder_exam_h2', 'Pengingat Jadwal Seleksi H-2', 'whatsapp', NULL, '🔔 *PENGINGAT JADWAL SELEKSI (H-2)*\n\nHalo *{nama_peserta}*,\nMengingatkan kembali bahwa Ujian/Seleksi *{nama_ujian}* Anda akan dilaksanakan dalam *2 hari lagi*:\n\n📆 Tanggal: *{tanggal}*\n⏰ Waktu: *{waktu}*\n📍 Lokasi/Link: *{lokasi_atau_link}*\n\nMohon persiapkan diri dan perangkat Anda dengan baik. Informasi detail dapat dilihat di: {link_aplikasi}', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1022-reminder-exam-h1', 'reminder_exam_h1', 'Pengingat Jadwal Seleksi H-1 (Besok)', 'whatsapp', NULL, '🔔 *PENGINGAT JADWAL SELEKSI (H-1 / BESOK)*\n\nHalo *{nama_peserta}*,\nBesok adalah hari pelaksanaan Ujian/Seleksi *{nama_ujian}* Anda:\n\n📆 Tanggal: *{tanggal}*\n⏰ Waktu: *{waktu}*\n📍 Lokasi/Link: *{lokasi_atau_link}*\n\nHarap hadir/bergabung 15 menit sebelum waktu yang ditentukan. Semoga diberikan kelancaran dan kemudahan!', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
INSERT INTO `notification_templates` (`id`, `event_key`, `label`, `channel`, `email_subject`, `body`, `is_active`, `created_at`, `updated_at`) VALUES ('notiftmpl-1018-reminder-exam-1hour', 'reminder_exam_1hour', 'Pengingat Ujian 1 Jam Sebelum', 'whatsapp', NULL, '🔔 *PENGINGAT UJIAN (1 JAM LAGI)*\n\nHalo *{nama_peserta}*,\nMengingatkan kembali bahwa Ujian *{nama_ujian}* Anda akan dimulai *1 jam lagi* pada pukul *{waktu}*.\n\n📍 *Detail/Link:* *{lokasi_atau_link}*\n\nHarap segera bersiap dan gabung/hadir 15 menit sebelum sesi dimulai. Semoga sukses!', 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `label` = VALUES(`label`), `channel` = 'whatsapp', `email_subject` = NULL, `body` = VALUES(`body`), `is_active` = 1, `updated_at` = NOW();
